con:config.script:
def result=javax.swing.JOptionPane.showConfirmDialog( null,"In the \"smp.config.properties\" file, put \"identifiersBehaviour.ParticipantIdentifierScheme.validationRegex\" to \".*\"."); 
if(result == javax.swing.JOptionPane.YES_OPTION)
{
	log.info "continuing the test";
}
else if(result == javax.swing.JOptionPane.NO_OPTION)
{
	log.info "script aborted";
	testRunner.fail("Test aborted by user");
}

